use std::{fs,path::{Path,PathBuf},process::{Command,Stdio},collections::{BTreeMap,BTreeSet},io::Read,os::unix::fs::MetadataExt};use serde_json::{Value,json};use sha2::{Sha256,Digest};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists(),"already exists {}",p.as_ref().display());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap()}
fn walk(p:&Path,base:&Path,out:&mut BTreeMap<String,String>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();assert!(!e.file_type().unwrap().is_symlink());if e.file_type().unwrap().is_dir(){walk(&e.path(),base,out)}else{out.insert(e.path().strip_prefix(base).unwrap().to_str().unwrap().into(),hash(e.path()));}}}
fn state()->Value{let path=fs::read_to_string("/proc/self/cgroup").unwrap();let cg=path.lines().find_map(|l|l.strip_prefix("0::")).unwrap();let base=Path::new("/sys/fs/cgroup").join(cg.trim_start_matches('/'));let mut v=json!({"path":cg});for f in["memory.max","memory.swap.max","memory.events","memory.peak","cpu.max","cpu.stat","cpuset.cpus.effective"]{if let Ok(s)=fs::read_to_string(base.join(f)){v[f]=json!(s);}}v}
fn workflow(root:&Path,out:&Path,label:&str,steps:&[Value],pins:&Path){let plan=out.join(format!("{label}-plan.json"));save(&plan,json!({"version":1,"source_pins":pins,"steps":steps}));let log=fs::File::create(out.join(format!("{label}.log"))).unwrap();let status=Command::new(root.join("bin/xtask")).arg("workflow").arg(plan).arg(out.join(format!("{label}-run"))).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().unwrap();assert!(status.success(),"{label} failed; preserve output and resume only missing work");}
fn verify_step(root:&Path,j:&Value)->Value{let c=&j["case"];json!({"kind":"command","name":format!("verify-{}",j["name"].as_str().unwrap()),"argv":[root.join("bin/verify").to_str().unwrap(),root.join(c["image"].as_str().unwrap()).to_str().unwrap(),c["image_sha256"].as_str().unwrap(),format!("{}/0.proof",j["proof_dir"].as_str().unwrap()),format!("{}/0.public",j["proof_dir"].as_str().unwrap()),c["public_sha256"].as_str().unwrap()],"timeout_seconds":300})}
fn inspect(out:&Path,j:&Value,phase:&str,verify_phase:&str)->Value{let name=j["name"].as_str().unwrap();let dir=out.join(format!("{phase}-run/{name}"));let e=read(dir.join("exit.json"));assert_eq!(e["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(dir.join(format!("{s}.log"))),e[format!("{s}_sha256")].as_str().unwrap());}let text=fs::read_to_string(dir.join("stdout.log")).unwrap();let samples=text.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let summaries=text.lines().filter_map(|l|l.strip_prefix("SUMMARY ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(summaries.len(),1);let s=&summaries[0];let rounds=j["rounds"].as_u64().unwrap();let workers=j["workers"].as_u64().unwrap();assert_eq!(s["rounds"],rounds);assert_eq!(s["priming"],3);assert_eq!(samples.len(),rounds as usize);let z=j["engine"]=="zopro";let key=if z{"ms"}else{"verified_ms"};let mut sum=0.;for(i,v)in samples.iter().enumerate(){assert_eq!(v["round"],i);let x=v[key].as_f64().unwrap();assert!(x.is_finite()&&x>0.);sum+=x;if !z{assert_eq!(v["cache_hit"],true);}}
if z{assert_eq!(s["workers"],workers);let a=&s["placement_before"];assert_eq!(*a,s["placement_after"]);assert_eq!(a["mode"],"fixed");let rows=a["worker_rows"].as_array().unwrap();assert_eq!(rows.len(),workers as usize);for(i,w)in rows.iter().enumerate(){assert_eq!(w["index"],i);assert_eq!(w["allowed"],json!([i]));}assert_eq!(s["generated_timed_fixed_scans"],0);assert_eq!(s["generated_timed_key_scans"],0);}
else{assert_eq!(s["threads"],workers);assert_eq!(s["key_sha256"],"7ef987966b0dfba5d86eab7c67068be00dbe581d823d45cdbbf6d338bfacb640");}
let proof=PathBuf::from(format!("{}/0.proof",j["proof_dir"].as_str().unwrap()));let public=proof.with_file_name("0.public");assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert_eq!(hash(public),j["case"]["public_sha256"].as_str().unwrap());let proofhash=hash(proof);let vd=out.join(format!("{verify_phase}-run/verify-{name}"));assert_eq!(read(vd.join("exit.json"))["success"],true);let verified=fs::read_to_string(vd.join("stdout.log")).unwrap();assert!(verified.contains(&format!("VERIFIED proof_sha256={proofhash} ")));assert!(verified.contains(&format!(" image_sha256={}",j["case"]["image_sha256"].as_str().unwrap())));json!({"job":j,"mean_ms":sum/rounds as f64,"samples":samples,"summary":s,"proof_sha256":proofhash,"cpu_ms":(s["user_cpu_ms"].as_f64().unwrap()+s["system_cpu_ms"].as_f64().unwrap())/rounds as f64,"rss_mib":s["whole_process_maxrss_kib"].as_f64().unwrap()/1024.})}

